/** German dialogue for Rockland (Felsland), the third country of the adventure (A2). Merged into adventure.ts. */
import type { AdventurePart } from '../adventure-merge';
import type { Token } from '../types';

/**
 * A line from compact tokens: words "surface=gloss" or "surface=gloss=lemma" separated by "|"; a bare token is
 * punctuation.
 */
const L = (en: string, toks: string): { en: string; t: Token[] } => ({
  en,
  t: toks.split('|').map((s): Token => {
    const [w, g, lemma] = s.trim().split('=');
    if (g === undefined) return [w, '', ''];
    return lemma ? [w, '', g, lemma] : [w, '', g];
  }),
});

